#include "stdafx.h"#include "H_Class.h"static SBlockCreate AUXSUMMER( "AUXSUMMER", SH_AUXSUMMER::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_AUXSUMMER,W_AUXSUMMER,210)void SH_AUXSUMMER::InitParm(){#include "Blocks/AUXSUMMER.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/AUXSUMMER_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class AUXSUMMER_IMPL : public W_AUXSUMMER{public:  void StepT( SStepCalcParams &dt, bool (&bPconnected)[11] );};void SH_AUXSUMMER::StepAfterRestoreState(){  ZeroMemory( bPconnected, sizeof(bPconnected) );  ASSD( inConsC );  W->NUMPINPT = 0;  for( size_t i=0; i<inConsC; ++i )  {    SConnectionMB &con = pInConns[i];    if( '['==con.szInFld[1] && 'P'==con.szInFld[0] )    {      int index = atoi( con.szInFld+2 );      ASSD( index>0 && index<_countof(W->P));      bPconnected[index] = true;      ++W->NUMPINPT;    }  }}void SH_AUXSUMMER::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  AUXSUMMER_IMPL *impl = reinterpret_cast<AUXSUMMER_IMPL*>(W);  impl->StepT( dt, bPconnected );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void AUXSUMMER_IMPL::StepT( SStepCalcParams &dt, bool (&bPconnected)[11] ){  double cpdAll = 0;  bool bBadIn = false;  for( int i=1; i<_countof(P); ++i )  {    if( !bPconnected[i] )      continue;    double cpd = 0;    if( !PENABLE[i] )      cpd = PSUB[i];    else    {      if( IsNaN( P[i] ) )      {        PSTS[i] = _PSTS::BAD;        bBadIn = true;        continue;      }      else      {        PSTS[i] = _PSTS::NORMAL;        cpd = C[i]*P[i] + D[i];      }    }    cpdAll += cpd;  }  if( bBadIn )  {    PVSTS = _PVSTS::BAD;    PVSTSFL.BAD = true;    PVSTSFL.NORM = false;    PV = NaN;  }  else  {    PVSTS = _PVSTS::NORMAL;    PVSTSFL.BAD = false;    PVSTSFL.NORM = true;    PV = CPV * cpdAll + DPV;  }}